def decorator(func):
    def wrapper(*args, **kwargs):
        print("до")
        result = func(*args, **kwargs)
        print("после")
        return result
    return wrapper

@decorator
def hello():
    print("привет")

class Observer:
    def __init__(self):
        self.subs = []
    def subscribe(self, fn):
        self.subs.append(fn)
    def notify(self, data):
        for fn in self.subs:
            fn(data)

class Strategy:
    def __init__(self, func):
        self.func = func
    def execute(self, data):
        return self.func(data)

s = Strategy(lambda x: x * 2)
print(s.execute(5))
